// Gamerisen logo marks (Dark mode: White R / Light mode: Dark R)
export const LOGO_DARK_SRC = "data:image/png;base64,";
export const LOGO_LIGHT_SRC = "data:image/png;base64,";
export const LOGO_SRC = LOGO_DARK_SRC;

/**
 * Returns the proper theme-tailored logo source.
 * In dark mode: Red G + White R.
 * In light mode: Red G + Dark R.
 */
export function getLogoSrc(theme) {
  return theme === 'light' ? LOGO_LIGHT_SRC : LOGO_DARK_SRC;
}
